using Common.Resources.Proto;
using PemukulPaku.GameServer.Game;
namespace PemukulPaku.GameServer.Handlers;
[PacketCmdId(CmdId.GetConsignedOrderDataReq)] internal class GetConsignedOrderDataReqHandler:IPacketHandler{public void Handle(Session s,Packet p)=>s.Send(Packet.FromProto(ArmadaConsignedGameplay.Build(s.Player),CmdId.GetConsignedOrderDataRsp));}
[PacketCmdId(CmdId.GetNewConsignedOrderDataReq)] internal class GetNewConsignedOrderDataReqHandler:IPacketHandler{public void Handle(Session s,Packet p)=>s.Send(Packet.FromProto(ArmadaConsignedGameplay.New(s.Player),CmdId.GetNewConsignedOrderDataRsp));}
[PacketCmdId(CmdId.GetConsignedRewardReq)] internal class GetConsignedRewardReqHandler:IPacketHandler{public void Handle(Session s,Packet p)=>s.Send(Packet.FromProto(ArmadaConsignedGameplay.Rewards(s.Player),CmdId.GetConsignedRewardRsp));}
[PacketCmdId(CmdId.GetConsignedRewardLogReq)] internal class GetConsignedRewardLogReqHandler:IPacketHandler{public void Handle(Session s,Packet p)=>s.Send(Packet.FromProto(ArmadaConsignedGameplay.Log(s.Player),CmdId.GetConsignedRewardLogRsp));}
[PacketCmdId(CmdId.ChooseConsignedOrderReq)] internal class ChooseConsignedOrderReqHandler:IPacketHandler{public void Handle(Session s,Packet p){var r=ArmadaConsignedGameplay.Choose(s.Player,p.GetDecodedBody<ChooseConsignedOrderReq>());s.Send(Packet.FromProto(r,CmdId.ChooseConsignedOrderRsp));if(r.retcode==0)s.ProcessPacket(Packet.FromProto(new GetConsignedOrderDataReq(),CmdId.GetConsignedOrderDataReq));}}
[PacketCmdId(CmdId.FinishConsignedOrderReq)] internal class FinishConsignedOrderReqHandler:IPacketHandler{public void Handle(Session s,Packet p){var r=ArmadaConsignedGameplay.Finish(s.Player,p.GetDecodedBody<FinishConsignedOrderReq>());s.Send(Packet.FromProto(r,CmdId.FinishConsignedOrderRsp));if(r.retcode==0){DailyGameplay.PushInventory(s);DailyGameplay.PushDuty(s);s.ProcessPacket(Packet.FromProto(new GetConsignedOrderDataReq(),CmdId.GetConsignedOrderDataReq));ArmadaContributionGameplay.Push(s);}}}
[PacketCmdId(CmdId.TakeConsignedRewardReq)] internal class TakeConsignedRewardReqHandler:IPacketHandler{public void Handle(Session s,Packet p){var r=ArmadaConsignedGameplay.Take(s.Player,p.GetDecodedBody<TakeConsignedRewardReq>());s.Send(Packet.FromProto(r,CmdId.TakeConsignedRewardRsp));if(r.retcode==0){DailyGameplay.PushInventory(s);s.ProcessPacket(Packet.FromProto(new GetConsignedOrderDataReq(),CmdId.GetConsignedOrderDataReq));}}}
[PacketCmdId(CmdId.ChooseConsignedRewardReq)] internal class ChooseConsignedRewardReqHandler:IPacketHandler{public void Handle(Session s,Packet p)=>s.Send(Packet.FromProto(ArmadaConsignedGameplay.ChooseReward(s.Player,p.GetDecodedBody<ChooseConsignedRewardReq>()),CmdId.ChooseConsignedRewardRsp));}
[PacketCmdId(CmdId.ResetConsignedOrderReq)] internal class ResetConsignedOrderReqHandler:IPacketHandler{public void Handle(Session s,Packet p){var r=ArmadaConsignedGameplay.Reset(s.Player);s.Send(Packet.FromProto(r,CmdId.ResetConsignedOrderRsp));if(r.retcode==0)s.ProcessPacket(Packet.FromProto(new GetConsignedOrderDataReq(),CmdId.GetConsignedOrderDataReq));}}
[PacketCmdId(CmdId.TakeArmadaAchievementReq)] internal class TakeArmadaAchievementReqHandler:IPacketHandler{public void Handle(Session s,Packet p){var r=ArmadaContributionGameplay.Take(s.Player,p.GetDecodedBody<TakeArmadaAchievementReq>());s.Send(Packet.FromProto(r,CmdId.TakeArmadaAchievementRsp));if(r.retcode==0){DailyGameplay.PushInventory(s);ArmadaContributionGameplay.Push(s);}}}
[PacketCmdId(CmdId.MoveArmadaCabinReq)] internal class MoveArmadaCabinReqHandler:IPacketHandler{public void Handle(Session s,Packet p){var r=ArmadaConstructionGameplay.Move(s.Player,p.GetDecodedBody<MoveArmadaCabinReq>());s.Send(Packet.FromProto(r,CmdId.MoveArmadaCabinRsp));if(r.retcode==0)s.ProcessPacket(Packet.FromProto(new GetArmadaDataReq(),CmdId.GetArmadaDataReq));}}
[PacketCmdId(CmdId.CancelLevelUpArmadaCabinReq)] internal class CancelLevelUpArmadaCabinReqHandler:IPacketHandler{public void Handle(Session s,Packet p){var r=ArmadaConstructionGameplay.Cancel(s.Player,p.GetDecodedBody<CancelLevelUpArmadaCabinReq>());s.Send(Packet.FromProto(r,CmdId.CancelLevelUpArmadaCabinRsp));if(r.retcode==0)s.ProcessPacket(Packet.FromProto(new GetArmadaDataReq(),CmdId.GetArmadaDataReq));}}
